from pathlib import Path
import base64, gzip, subprocess

# V7.5.31 -> V7.5.33 deterministic production patch.
# Contains the graceful DATA_INCOMPLETE handling plus the max-12 dynamic watchlist.
PAYLOAD = ""
patch_bytes = gzip.decompress(base64.b64decode(PAYLOAD))
subprocess.run(["patch", "-p0", "--forward", "--batch"], input=patch_bytes, check=True)
text = Path("Worker.js").read_text(encoding="utf-8")
expected = 'const VERSION = "7.5.33-dynamic-watchlist-12";'
if expected not in text:
    raise SystemExit("V7.5.33 patch applied but expected version marker is missing")
for marker in [
    'const WATCHLIST_MAX = 12;',
    'function buildReviewedWatchlist(',
    'async function finishDataIncompleteScan(',
    'url.pathname === "/watchlist"',
    'watchlistUrl: WATCHLIST_URL'
]:
    if marker not in text:
        raise SystemExit(f"V7.5.33 patch verification failed: missing {marker}")
print("Applied V7.5.33 DATA_INCOMPLETE + dynamic watchlist patch")
